-- Two SEO-focused Kenya guides with official data verified as at 16 October 2026.
-- Passport fees and validity: Immigration Department (immigration.go.ke). Business fees: BRS fee schedule (brs.go.ke).

INSERT IGNORE INTO guides
(title, slug, category, summary, intro, content_html, meta_title, meta_description, status, published_at)
VALUES (
'How to Apply for a Passport in Kenya: 2026 Fees, Requirements and Timelines',
'how-to-apply-for-a-passport-in-kenya',
'Government documents',
'A step-by-step guide to applying for a Kenyan ePassport through eCitizen: current Immigration Department fees from KSh 7,550 to KSh 12,050, required documents, the biometrics appointment and realistic processing timelines.',
'A Kenyan ePassport is applied for online through eCitizen, paid for digitally and collected in person after a biometrics appointment. The steps below reflect the official process as at October 2026, including the current Immigration Department fee schedule.',
'<p>For first-time applicants the process feels longer online than it really is: create an eCitizen account, complete the passport application, pay the Government fee, book an appointment at an Immigration office, attend for fingerprints and a photograph, then collect the passport when you receive notification. Here is what each step involves and what to budget.</p><h2>1. What it costs in 2026</h2><p>The Immigration Department sets the following official fees for ordinary ePassports. Fees can be revised, so confirm on the official portal before paying.</p><table><thead><tr><th>Passport type</th><th>Official fee (KES)</th></tr></thead><tbody><tr><td>Ordinary A Series (34 pages)</td><td>7,550</td></tr><tr><td>Ordinary B Series (50 pages)</td><td>9,550</td></tr><tr><td>Ordinary C Series (66 pages)</td><td>12,050</td></tr><tr><td>Replacement of a lost or mutilated passport</td><td>20,050</td></tr></tbody></table><p>Payment is made through eCitizen, usually by M-Pesa or card. Choose the page count based on how often you travel: frequent travellers generally benefit from the 50 or 66 page booklets.</p><h2>2. What you need before you start</h2><ul><li>A valid Kenyan National Identity card (the name on your ID should match your citizenship documents).</li><li>A Kenyan citizenship basis, normally shown by your ID, birth certificate or notification of birth.</li><li>An eCitizen account linked to your ID number and phone number.</li><li>For applicants under 18: the birth certificate plus the ID and consent of a parent or legal guardian.</li></ul><h2>3. Applying step by step</h2><p>Sign in to eCitizen and open the Immigration Services Department passport application. Complete the form with your personal details exactly as they appear on your ID, select the passport series and pay the fee. After payment you book an appointment at a convenient office, for example Nyayo House in Nairobi or a regional Immigration office. Attend in person on the appointment date for fingerprinting and a digital photograph, and keep the receipt and appointment slip.</p><h2>4. How long it takes</h2><p>Once your application and biometrics are captured, the official guidance is a minimum of about ten working days before collection, with two to four weeks being a realistic window at busier offices. You are notified by SMS or email when the passport is ready, and collection is in person with your ID. Plan well ahead of any travel dates rather than assuming expedited handling.</p><h2>5. Validity and renewal</h2><p>Kenyan ePassports are valid for ten years and are not renewable. When a passport expires, or is close to expiring, you apply for a new one. Many destinations also require at least six months of remaining validity and one or two blank pages, so renew early rather than at the last minute.</p><h2>6. Replacements, damage and applying from abroad</h2><p>A lost passport should be reported promptly and replaced at the lost or mutilated passport fee; a police abstract is commonly required. If you are outside Kenya, applications are handled by the nearest Kenyan embassy or high commission, with fees set in local currency by that mission.</p><h2>7. Common reasons applications stall</h2><ul><li>Name or date-of-birth mismatches between the ID, birth records and the application form.</li><li>Missing citizenship documents for first-time applicants.</li><li>Not attending the biometrics appointment, or arriving without the original ID.</li><li>Assuming a renewal can be done by post: collection is in person.</li></ul><p><em>Information is current as at 16 October 2026 and reflects published Immigration Department guidance. Fees and timelines can change. AlbaTech Solutions is an independent assistance provider and is not affiliated with the Department of Immigration Services.</em></p>',
'How to Apply for a Passport in Kenya (2026): Fees, Steps & Timelines',
'Apply for a Kenyan ePassport through eCitizen in 2026: official fees from KSh 7,550 to KSh 12,050, required documents, biometrics appointment, processing timelines and 10-year validity.',
'published',
'2026-10-16 09:00:00'
);

INSERT IGNORE INTO guides
(title, slug, category, summary, intro, content_html, meta_title, meta_description, status, published_at)
VALUES (
'How to Register a Business in Kenya (2026): Sole Proprietor vs Limited Company',
'how-to-register-a-business-in-kenya',
'Business registration',
'Compare Kenyan business structures and official 2026 costs, from a KSh 950 business name to a KSh 10,650 limited company, with the eCitizen BRS steps, required documents and the tax compliance that follows.',
'Registering a business in Kenya is done online through the Business Registration Service on eCitizen, and for most founders the real decision is between a simple business name and a limited liability company. This guide covers the official costs as at October 2026, the documents you need and what happens after approval.',
'<p>A registration certificate is the starting point, not the finish line: the structure you choose determines your liability, your filing duties and how customers and suppliers treat you. Here is how to decide and then complete the registration.</p><h2>1. Choose the right structure</h2><ul><li><strong>Sole proprietorship (business name):</strong> the simplest and cheapest option. You and the business are legally the same person, so you keep all profits but also carry all liability personally.</li><li><strong>Partnership:</strong> two to twenty partners share ownership and, in an ordinary partnership, personal liability.</li><li><strong>Private limited company (Ltd):</strong> a separate legal entity with limited liability, its own tax obligations, directors and shareholders. The usual choice for growing businesses, contracts and investor-readiness.</li><li><strong>Limited liability partnership (LLP):</strong> popular with professional firms, combining partnership flexibility with limited liability.</li></ul><h2>2. What it costs in 2026</h2><p>Official Government fees published in the BRS fee schedule include the following. Fees can be revised, so confirm on brs.go.ke before filing, and note that a company also pays a small name reservation charge and any professional support you choose to use.</p><table><thead><tr><th>Registration</th><th>Official fee (KES)</th><th>Typical turnaround</th></tr></thead><tbody><tr><td>Business name (sole proprietor or partnership)</td><td>950</td><td>About 1 working day</td></tr><tr><td>Private limited company</td><td>10,650</td><td>Roughly 3 to 7 working days</td></tr><tr><td>Limited liability partnership</td><td>25,000</td><td>Varies with review</td></tr></tbody></table><h2>3. Documents you will need</h2><ul><li>Original ID numbers and KRA PINs for the owner, or for all directors and shareholders of a company.</li><li>Two or three proposed business or company names, since similar existing names are rejected.</li><li>A physical and postal address description, phone numbers and email for the business.</li><li>For companies: director consent, shareholding structure, secretary details (a qualified secretary is required) and the registered office.</li></ul><h2>4. The registration steps on eCitizen</h2><p>Create or sign in to your eCitizen account and open the Business Registration Service. Run a name search and reserve the name, then complete the application form for the chosen structure, upload the required documents and pay the Government fee. The Registrar reviews the filing; on approval you receive a registration certificate for a business name, or a certificate of incorporation and CR12 for a company. A newly incorporated company is normally issued a company KRA PIN as part of incorporation.</p><h2>5. After registration: the compliance people forget</h2><ul><li><strong>KRA returns:</strong> file the applicable tax returns on time from day one, including PAYE and withholding tax once you have employees or contractors.</li><li><strong>eTIMS:</strong> KRA is expanding electronic tax invoicing, and from 2026 declared income and expenses are increasingly matched against eTIMS invoice data.</li><li><strong>Annual returns:</strong> companies and LLPs must file annual returns with the Registrar through BRS; late filing attracts penalties and prolonged non-filing risks strike-off.</li><li><strong>Beneficial ownership:</strong> companies must lodge and maintain a beneficial ownership register with the Registrar.</li><li><strong>County permits:</strong> most businesses also need a single business permit from the county government where they operate.</li></ul><h2>6. Common mistakes to avoid</h2><ul><li>Picking a name too close to an existing registration, which wastes the search fee and delays approval.</li><li>Registering a business name believing it creates limited liability: it does not.</li><li>Ignoring annual returns and tax filings because the business is quiet; penalties accumulate regardless.</li><li>Using personal KRA PINs informally for a company, which creates audit problems later.</li></ul><p><em>Information is current as at 16 October 2026 and reflects published BRS and KRA guidance. Fees and requirements can change. AlbaTech Solutions is an independent assistance provider and is not affiliated with the Business Registration Service or KRA.</em></p>',
'How to Register a Business in Kenya (2026): Costs, Steps & Structures',
'Register a business in Kenya in 2026: business name at KSh 950 or limited company at KSh 10,650 through eCitizen BRS. Compare structures, required documents and tax compliance.',
'published',
'2026-10-16 10:00:00'
);
